import{_ as e,o as a,c as i,a2 as s}from"./chunks/framework.D66Xq0Kv.js";const u=JSON.parse('{"title":"Trustville labs","description":"","frontmatter":{},"headers":[],"relativePath":"labs/index.md","filePath":"labs/README.md","lastUpdated":null}'),n={name:"labs/index.md"};function r(o,t,d,h,l,p){return a(),i("div",null,[...t[0]||(t[0]=[s(`<h1 id="trustville-labs" tabindex="-1">Trustville labs <a class="header-anchor" href="#trustville-labs" aria-label="Permalink to &quot;Trustville labs&quot;">​</a></h1><p>Six labs. In each one you ship a feature into a working dApp: contract, tests, interface, and a pull request that survives review.</p><p>This is not a tour of the town. You will have used the site in week one and that is the end of it as an activity. From lab 1 onward Trustville is the codebase you work in, and the standard is the one applied to a junior full stack engineer in their first months: <strong>does it work, does it fail safely, is it tested, and can someone else maintain it?</strong></p><table tabindex="0"><thead><tr><th>Lab</th><th>You ship</th><th>The skill being hired for</th></tr></thead><tbody><tr><td><a href="./lab-1-shipping-your-first-change">1</a></td><td>A working dev environment and a first merged PR</td><td>Reading an unfamiliar codebase and changing it safely</td></tr><tr><td><a href="./lab-2-reading-the-chain">2</a></td><td>An activity feed built from event logs</td><td>Getting data out of a chain without an indexer</td></tr><tr><td><a href="./lab-3-writing-transactions">3</a></td><td>A certificate issue-and-verify flow</td><td>The transaction lifecycle, and every way it fails</td></tr><tr><td><a href="./lab-4-a-vertical-slice">4</a></td><td>A contract change and the interface for it</td><td>Contract and frontend as one change</td></tr><tr><td><a href="./lab-5-state-machines-and-time">5</a></td><td>The governance interface, done properly</td><td>Modelling a contract&#39;s state machine in a UI</td></tr><tr><td><a href="./lab-6-money-prices-and-failure">6</a></td><td>Trading, borrowing, and an attack write-up</td><td>Handling money in an interface, and reporting when it goes wrong</td></tr></tbody></table><h2 id="the-standard" tabindex="-1">The standard <a class="header-anchor" href="#the-standard" aria-label="Permalink to &quot;The standard&quot;">​</a></h2><p>Every lab is delivered as a <strong>pull request against your fork</strong>. It is marked the way a PR is marked at work.</p><p><strong>Definition of done.</strong> A PR is finished when:</p><ul><li>CI is green — contracts build optimized, tests pass, <code>forge fmt</code> is clean, the app builds, and no secret is in the diff.</li><li>Tests cover the happy path <strong>and each way the thing can fail</strong>. A test suite that only proves the good case is not evidence.</li><li>The interface handles: wallet rejected, transaction reverted, wrong network, insufficient funds, and a pending transaction. A spinner that never resolves is a bug, not a state.</li><li>Custom errors are decoded and shown as something a user can act on. <code>0x7939f424</code> is not an error message.</li><li>The PR description explains <strong>why</strong>, not what. The diff already says what.</li><li>A peer has reviewed it and you have addressed the comments. &quot;Addressed&quot; includes disagreeing, with a reason.</li></ul><p><strong>Incidents.</strong> Each lab also needs one write-up in <code>docs/incidents/</code> when something breaks — a failed deploy, a wrong address, a transaction that did something you did not intend. Use <a href="./../INCIDENT">the template</a>. Over six labs, &quot;nothing broke&quot; will not be true.</p><p>Blameless means naming systems rather than people. &quot;I forgot to grant the role&quot; describes the outcome. &quot;The deploy script printed the grant command and nothing verified it had been run, so a missing role looked identical to a working deployment&quot; describes the cause, and it produces a fix.</p><h2 id="how-you-work" tabindex="-1">How you work <a class="header-anchor" href="#how-you-work" aria-label="Permalink to &quot;How you work&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> checkout</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -b</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lab-3-certificates</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># ... build it ...</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> contracts</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; FOUNDRY_PROFILE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">test</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> forge</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ..</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> push</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> origin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lab-3-certificates</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># open the PR, request a reviewer</span></span></code></pre></div><p>Small commits with honest messages. Rebase rather than merge-commit your own branch. If CI is red, it is red for you too — do not ask a reviewer to look at a broken branch.</p><p><strong>Review is half the job.</strong> You will review a classmate&#39;s PR in every lab, and that review is marked. A review that says &quot;looks good&quot; is worth nothing; the ones that count find a missing failure state, an unhandled revert, or a design that will not survive its second requirement.</p><h2 id="how-it-is-marked" tabindex="-1">How it is marked <a class="header-anchor" href="#how-it-is-marked" aria-label="Permalink to &quot;How it is marked&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td>It works — meets the spec, CI green</td><td>30%</td></tr><tr><td>It fails well — every failure state handled and shown honestly</td><td>25%</td></tr><tr><td>Tests — happy path and failure paths, meaningful assertions</td><td>20%</td></tr><tr><td>The PR itself — description, commits, reviewability</td><td>15%</td></tr><tr><td>Your review of someone else&#39;s PR</td><td>10%</td></tr></tbody></table><p>Note what is not on that list: using the site, and finishing quickly. The passport stamps record that you performed a transaction. They are a warm-up, not a grade.</p><h2 id="before-lab-1" tabindex="-1">Before lab 1 <a class="header-anchor" href="#before-lab-1" aria-label="Permalink to &quot;Before lab 1&quot;">​</a></h2><ul><li>Node 20+, Foundry, git, a GitHub account.</li><li>MetaMask with a <strong>fresh wallet made for this course</strong>, funded from the faucet.</li><li>Your own fork of the repository, cloned, with <code>npm run local</code> working.</li></ul><p>If <code>npm run local</code> does not give you a working town on localhost, you cannot start lab 1. Fix that first — and if fixing it takes you two hours, that was lab 0 and it was not wasted.</p><h2 id="a-note-on-the-chain" tabindex="-1">A note on the chain <a class="header-anchor" href="#a-note-on-the-chain" aria-label="Permalink to &quot;A note on the chain&quot;">​</a></h2><p>DIDLab is a permissioned chain with free gas and instant finality. That is a teaching convenience and also a distortion: on a public chain your transaction competes for space, costs real money, and may be front-run by someone reading the mempool. Where a design depends on that difference, the labs say so. Do not learn habits here that will cost somebody money later.</p>`,22)])])}const k=e(n,[["render",r]]);export{u as __pageData,k as default};
